'use strict';
(()=>{
const $=s=>document.querySelector(s),rooms=F_DATA.rooms.filter(r=>r.floor==='1F'),params=new URLSearchParams(location.search);
const normalize=s=>s.normalize('NFKC').toUpperCase().replace(/[\s._—–-]/g,'');const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let selected=rooms.find(r=>r.id===params.get('room'))||rooms.find(r=>r.id==='F-1021'),origin=null,model=null,top=false,picking=false,navOpen=false;
function resultList(){const q=normalize($('#search-input').value),found=rooms.filter(r=>!q||normalize(r.id).includes(q)||r.label.includes(q));$('#result-count').textContent=q?`${found.length} 个结果 · F 栋一层`:'选择一层房间';$('#search-results').innerHTML=found.length?found.map(r=>`<button class="result ${r.id===selected.id?'current':''}" data-room="${r.id}"><span class="result-icon">⌖</span><span><strong>${r.id}</strong><small>${r.label==='用途待确认'?'F 栋 · 一层':escape(r.label)}</small></span><span class="arrow">↗</span></button>`).join(''):'<p class="empty">本层未找到这个编号。<br>目前仅提供 F 栋一层的 sample。</p>';$('#clear-search').hidden=!$('#search-input').value;}
function openSearch(){resultList();$('#search-panel').hidden=false;$('#search-input').setAttribute('aria-expanded','true')}
function closeSearch(){$('#search-panel').hidden=true;$('#search-input').setAttribute('aria-expanded','false');$('#search-input').blur()}
function render(){$('#room-name').textContent=selected.id;$('#room-use').textContent=selected.label==='用途待确认'?'F 栋 · 一层':selected.label;$('#nav-destination').textContent=selected.id;model?.setSelected(selected.id);model?.setMarkers(origin,navOpen||origin?selected:null);$('#show-journey').disabled=!origin;$('#show-journey').textContent=origin?'查看起终点':'请先选择起点';$('#nav-status').textContent=origin?.id===selected.id?'起点与目的地是同一教室。':origin?'已选择起终点。路线待实地核验，暂不提供转弯指引。':'本 sample 可选择起终点，导航路线待实地核验。';}
function selectRoom(id){const r=rooms.find(r=>r.id===id);if(!r)return;selected=r;$('#search-input').value=r.id;$('#clear-search').hidden=false;closeSearch();render();model?.focus(id);const url=new URL(location);url.searchParams.set('room',id);url.searchParams.delete('q');history.replaceState(null,'',url);}
function navigation(open){navOpen=open;$('#navigation').hidden=!open;$('#destination-card').hidden=open;$('.app').classList.toggle('nav-open',open);render();}
function setPicking(on){picking=on;model?.setPicking(on);$('.app').classList.toggle('picking',on);$('#pick-tip').hidden=!on;$('#navigation').hidden=on||!navOpen;$('#destination-card').hidden=on||navOpen;if(on){closeSearch();model?.fit();}}
function modal(title,html){$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=html;if(!$('#info-dialog').open)$('#info-dialog').showModal()}
function source(page){modal('原图核对',`<p>F 栋一层 · 展示牌照片第 ${page} 页</p><a href="f-assets/source-${String(page).padStart(2,'0')}.jpg" target="_blank" rel="noopener">打开原始照片 ↗</a><img class="source-photo" src="f-assets/source-${String(page).padStart(2,'0')}.jpg" alt="F 栋一层展示牌原始照片第 ${page} 页">`)}
$('#origin-select').innerHTML+='<option value="manual" disabled>地图上的手动位置</option>'+rooms.map(r=>`<option value="${r.id}">${r.id}${r.label!=='用途待确认'?' · '+escape(r.label):''}</option>`).join('');
$('#search-input').onfocus=openSearch;$('#search-input').oninput=openSearch;$('#search-input').onkeydown=e=>{if(e.key==='Escape')closeSearch()};$('#search-form').onsubmit=e=>{e.preventDefault();const first=$('#search-results [data-room]');if(first)selectRoom(first.dataset.room)};$('#search-results').onclick=e=>{const b=e.target.closest('[data-room]');if(b)selectRoom(b.dataset.room)};$('#close-search').onclick=closeSearch;$('#clear-search').onclick=()=>{$('#search-input').value='';openSearch();$('#search-input').focus()};
$('#go').onclick=()=>{closeSearch();navigation(true)};$('#close-nav').onclick=()=>{setPicking(false);navigation(false)};$('#change-destination').onclick=()=>{$('#search-input').value='';openSearch();$('#search-input').focus()};$('#origin-select').onchange=e=>{origin=rooms.find(r=>r.id===e.target.value)||null;render()};$('#pick-position').onclick=()=>setPicking(true);$('#cancel-pick').onclick=()=>setPicking(false);$('#show-journey').onclick=()=>{navigation(false);model?.setMarkers(origin,selected);model?.fit()};
function updateView(){$('#view-toggle').textContent=top?'3D':'2D';$('#view-toggle').setAttribute('aria-label',top?'切换到三维地图':'切换到俯视地图')}
$('#fit').onclick=()=>{model?.fit();top=false;updateView()};$('#zoom-in').onclick=()=>model?.zoom(.75);$('#zoom-out').onclick=()=>model?.zoom(1.3);$('#view-toggle').onclick=()=>{top=!top;if(top)model?.setTopView();else model?.fit();updateView()};
$('#about').onclick=()=>modal('关于这张地图',`<p>F 栋一层 sample：搜索教室、查看三维位置、选择起终点。</p><p>房间依据展示牌描摹，墙高为示意。黄色问号表示编号有待核对；模型未经实地测绘。当前没有自动定位或已核验的导航路线。</p><button class="dialog-action" id="view-source">核对原始平面图 ↗</button>`);$('#dialog-body').onclick=e=>{if(e.target.id==='view-source')source(1)};$('#close-dialog').onclick=()=>$('#info-dialog').close();
window.addEventListener('f-model-ready',e=>{model=e.detail;$('#loading').hidden=true;model.setActive(true);render();if(params.get('room'))model.focus(selected.id)});window.addEventListener('f-model-error',()=>{$('#loading').hidden=true;$('#model-host').hidden=true;$('#map-fallback').hidden=false;$('.map-toolbar').hidden=true;$('#pick-position').disabled=true});
window.addEventListener('f-model-select',e=>selectRoom(e.detail));window.addEventListener('f-model-position',e=>{origin={floor:'1F',...e.detail};$('#origin-select').value='manual';setPicking(false);render()});window.addEventListener('f-model-source',e=>source(e.detail));window.addEventListener('f-model-issue',e=>{const issue=F_DATA.issues.find(i=>i.id===e.detail);if(issue)modal('这个位置待核对',`<p>${escape(issue.detail)}</p><button class="dialog-action" id="view-source">查看原始平面图 ↗</button>`)});
document.addEventListener('pointerdown',e=>{if(!e.target.closest('.search-area'))closeSearch()});document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(picking)setPicking(false);else if(navOpen)navigation(false)}});render();if(params.get('q')){$('#search-input').value=params.get('q');openSearch()}
})();
